import java.util.*;
import java.io.*;

public class MinCostFlowJava {

    static class Edge {
        int to, rev;
        long capacity, cost;

        public Edge(int to, int rev, long capacity, long cost) {
            this.to = to;
            this.rev = rev;
            this.capacity = capacity;
            this.cost = cost;
        }
    }

    static class MinCostFlowGraph {
        int n;
        List<List<Edge>> adj;
        List<int[]> edgesPos;
        long[] potential;
        int[] prevVertex, prevEdge;
        long[] dist;
        boolean[] visited;

        public MinCostFlowGraph(int n) {
            this.n = n;
            adj = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                adj.add(new ArrayList<>());
            }
            edgesPos = new ArrayList<>();
        }

        public int addEdge(int from, int to, long capacity, long cost) {
            int index = edgesPos.size();
            edgesPos.add(new int[]{from, adj.get(from).size()});
            adj.get(from).add(new Edge(to, adj.get(to).size(), capacity, cost));
            adj.get(to).add(new Edge(from, adj.get(from).size() - 1, 0, -cost));
            return index;
        }

        public Edge getEdge(int i) {
            int[] pos = edgesPos.get(i);
            Edge e = adj.get(pos[0]).get(pos[1]);
            Edge re = adj.get(e.to).get(e.rev);
            return new Edge(pos[0], e.to, e.capacity + re.capacity, e.cost);
        }

        public List<Edge> allEdges() {
            List<Edge> result = new ArrayList<>();
            for (int i = 0; i < edgesPos.size(); i++) {
                int[] pos = edgesPos.get(i);
                Edge e = adj.get(pos[0]).get(pos[1]);
                Edge re = adj.get(e.to).get(e.rev);
                result.add(new Edge(pos[0], e.to, e.capacity + re.capacity, e.cost));
            }
            return result;
        }

        private boolean findShortestPath(int s, int t) {
            dist = new long[n];
            Arrays.fill(dist, Long.MAX_VALUE);
            prevVertex = new int[n];
            prevEdge = new int[n];
            visited = new boolean[n];

            PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            dist[s] = 0;
            pq.offer(new long[]{0, s});

            while (!pq.isEmpty()) {
                long[] curr = pq.poll();
                int v = (int) curr[1];
                if (visited[v]) continue;
                visited[v] = true;
                if (v == t) break;
                for (int i = 0; i < adj.get(v).size(); i++) {
                    Edge e = adj.get(v).get(i);
                    if (visited[e.to] || e.capacity == 0) continue;
                    long newDist = dist[v] + e.cost;
                    if (dist[e.to] > newDist) {
                        dist[e.to] = newDist;
                        prevVertex[e.to] = v;
                        prevEdge[e.to] = i;
                        pq.offer(new long[]{dist[e.to], e.to});
                    }
                }
            }
            if (!visited[t]) return false;
            potential = new long[n];
            for (int v = 0; v < n; v++) {
                if (visited[v]) {
                    potential[v] -= dist[t];
                }
            }
            return true;
        }

        public List<long[]> minCostFlow(int s, int t, long flowLimit) {
            long flow = 0;
            long cost = 0;
            List<long[]> results = new ArrayList<>();
            results.add(new long[]{flow, cost});
            while (flow < flowLimit) {
                if (!findShortestPath(s, t)) break;
                long c = flowLimit - flow;
                int v = t;
                while (v != s) {
                    int u = prevVertex[v];
                    Edge e = adj.get(u).get(prevEdge[v]);
                    c = Math.min(c, e.capacity);
                    v = u;
                }
                v = t;
                while (v != s) {
                    int u = prevVertex[v];
                    Edge e = adj.get(u).get(prevEdge[v]);
                    e.capacity -= c;
                    adj.get(v).get(e.rev).capacity += c;
                    v = u;
                }
                long delta = -potential[s];
                flow += c;
                cost += c * delta;
                if (results.get(results.size() - 1)[1] == cost) {
                    results.remove(results.size() - 1);
                }
                results.add(new long[]{flow, cost});
            }
            return results;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] data = br.readLine().split(" ");
        int n = Integer.parseInt(data[0]);
        int[] a = new int[3];
        int[] b = new int[3];
        data = br.readLine().split(" ");
        for (int i = 0; i < 3; i++) {
            a[i] = Integer.parseInt(data[i]);
        }
        data = br.readLine().split(" ");
        for (int i = 0; i < 3; i++) {
            b[i] = Integer.parseInt(data[i]);
        }

        MinCostFlowGraph g = new MinCostFlowGraph(8);
        g.addEdge(0, 1, a[0], 0);
        g.addEdge(0, 2, a[1], 0);
        g.addEdge(0, 3, a[2], 0);
        g.addEdge(4, 7, b[0], 0);
        g.addEdge(5, 7, b[1], 0);
        g.addEdge(6, 7, b[2], 0);

        for (int i = 1; i <= 3; i++) {
            for (int j = 4; j <= 6; j++) {
                long cost = ((j - i) % 3 == 1) ? 1 : 0;
                g.addEdge(i, j, Long.MAX_VALUE, cost);
            }
        }

        List<long[]> flowResult = g.minCostFlow(0, 7, (1L << 32) - 1);
        long ans1 = flowResult.get(flowResult.size() - 1)[0];
        long ans2 = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
        System.out.println(ans1 + " " + ans2);
    }
}

